import sailpoint.api.CorrelationModel;
import sailpoint.object.Configuration;

boolean asyncRefresh = context.getConfiguration().getBoolean(Configuration.ASYNC_CACHE_REFRESH);
int asyncRefreshRequests = CorrelationModel.getAsyncRefreshRequests();
int cacheLoads = CorrelationModel.getCacheLoads();

Map deets = new HashMap();
deets.put("asyncRefresh", asyncRefresh);
deets.put("asyncRefreshRequests", asyncRefreshRequests);
deets.put("cacheLoads", cacheLoads);

return deets;
